#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int a[10][10];
    int zr = -1, zc = -1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
            if (a[i][j] == 0) {
                zr = i;
                zc = j;
            }
        }
    }

    int magic = 0;
    for (int i = 0; i < n; i++) {
        if (i == zr) continue;

        int sum = 0;
        for (int j = 0; j < n; j++) {
            sum += a[i][j];
        }
        magic = sum;
        break;
    }

    int rowSum = 0;
    for (int j = 0; j < n; j++) {
        rowSum += a[zr][j];
    }

    int value = magic - rowSum;

    printf("%d\n%d\n%d\n", value, zr + 1, zc + 1);

    return 0;
}
